     6	/**
     7	 * What every CSV report has in common: a title line (inn, report name and period), then the header, the rows
     8	 * and the total line. A report only says what its table holds; the shape of the file is written here, once.
     9	 */
    10	public abstract class CsvReport<P> {
    11	
    12	    private static final String INN = "Pousada Maré Alta";
    13	
    14	    /** The report's name, as it appears in the title line and in the URL. */
    15	    public abstract String name();
    16	
    17	    protected abstract Table table(P period);
    18	
    19	    public final String generate(P period) {
    20	        Table table = table(period);
    21	        StringBuilder csv = new StringBuilder();
    22	        csv.append(line(INN, name(), period)).append('\n');
    23	        csv.append(table.header()).append('\n');
    24	        for (String row : table.rows()) {
    25	            csv.append(row).append('\n');
    26	        }
    27	        csv.append(table.total()).append('\n');
    28	        return csv.toString();
    29	    }
    30	
    31	    protected static String line(Object... cells) {
    32	        StringJoiner line = new StringJoiner(",");
    33	        for (Object cell : cells) {
    34	            line.add(String.valueOf(cell));
    35	        }
    36	        return line.toString();
    37	    }
    38	
    39	    /** The header line, the data lines and the total line, each without the line break. */
    40	    protected record Table(String header, List<String> rows, String total) {
    41	    }
    42	}
