    50	package hotel.reports;
    51	
    52	import hotel.reservations.Reservation;
    53	import hotel.reservations.ReservationStore;
    54	import java.math.BigDecimal;
    55	import java.math.RoundingMode;
    56	import java.time.YearMonth;
    57	import java.util.ArrayList;
    58	import java.util.List;
    59	
    60	/** The city's tourism tax on the paid reservations that start in a month: a fee per guest per night (CSV). */
    61	public final class TourismTaxReport extends MonthlyReport {
    62	
    63	    private final ReservationStore store;
    64	    private final BigDecimal feePerGuestNight;
    65	
    66	    public TourismTaxReport(ReservationStore store, BigDecimal feePerGuestNight) {
    67	        this.store = store;
    68	        this.feePerGuestNight = feePerGuestNight;
    69	    }
    70	
    71	    @Override
    72	    public String name() {
    73	        return "tourism-tax";
    74	    }
    75	
    76	    @Override
    77	    protected Table table(YearMonth month) {
    78	        List<String> rows = new ArrayList<>();
    79	        BigDecimal total = BigDecimal.ZERO.setScale(2);
    80	        for (Reservation reservation : MonthReservations.paid(store, month)) {
    81	            int nights = reservation.price().nights();
    82	            BigDecimal tax = feePerGuestNight.multiply(BigDecimal.valueOf((long) reservation.guests() * nights))
    83	                    .setScale(2, RoundingMode.HALF_EVEN);
    84	            rows.add(line(reservation.id(), reservation.roomNumber(), reservation.checkIn(),
    85	                    reservation.checkOut(), reservation.guests(), nights, tax.toPlainString()));
    86	            total = total.add(tax);
    87	        }
    88	        return new Table("reservation,room,check_in,check_out,guests,nights,tax", rows,
    89	                line("total", total.toPlainString()));
    90	    }
    91	}
